text:
{
  "osszkep": "A szöveg összességében közvetlen és jól felépített, de helyenként szószaporító, kissé darabos, vagy a banki-nyugodt hangvételhez képest túl nyers. Néhány apró finomítással sokkal gördülékenyebb, emberibb és könnyebben felolvasható lesz egy 60 éves vállalkozó számára is.",
  "javaslatok": [
    {
      "id": "L03",
      "gond": "A 'valódi ember' kifejezés ebben a formában kissé rideg és magyarázkodó; a privátbanki, megnyugtató hangvételhez jobban illik a személyesség hangsúlyozása.",
      "uj_szoveg": "Saját könyvelőt kapsz: egy hús-vér szakembert, aki kézben tartja az adóügyeidet."
    },
    {
      "id": "L07",
      "gond": "A 'bekötés' kifejezés az ügyfél szemszögéből szakzsargon vagy műszaki jellegű, a 'mi ez' pedig kissé pongyola.",
      "uj_szoveg": "Előtte pár egyszerű lépés vár rád. Mindenhol leírtuk, mit kell tenned, és miért."
    },
    {
      "id": "L11",
      "gond": "A 'megadod a kártyádat' kissé nyers, bizalmatlanságot ébreszthet egy idősebb vállalkozóban.",
      "uj_szoveg": "Aztán elfogadod a szerződést, és beállítod a bankkártyádat a havidíjhoz."
    },
    {
      "id": "L12",
      "gond": "Az 'adószám után kérjük' mondatrész hiányos és nehezen értelmezhető beszédben (mikor/mit kérünk).",
      "uj_szoveg": "Ha most indítasz új vállalkozást, a kártyaadatokat csak az adószámod megszerzése után kérjük."
    },
    {
      "id": "L13",
      "gond": "Kétszer szerepel a mondatban az 'ad/adsz' tő ('adsz', 'adod meg'), az 'ONYA' rövidítés pedig kimondva idegenül és ijesztően hathat egy laikusnak feloldás vagy lágyítás nélkül.",
      "uj_szoveg": "Ezután NAV-meghatalmazást állítasz ki a könyvelődnek az online felületen, az alkalmazás segítségével."
    },
    {
      "id": "L15",
      "gond": "A 'személyidet' kissé szleng, a 'lakcímkártyád lakcímes oldalát' pedig szóismétlő és nyelvtörő.",
      "uj_szoveg": "Utána lefotózod a személyi igazolványodat és a lakcímkártyádat."
    },
    {
      "id": "L16",
      "gond": "A törvény nem 'kér', hanem előír, de beszélt nyelven barátságosabb megfogalmazás szükséges.",
      "uj_szoveg": "Ezt a törvény írja elő: minden ügyfelünket azonosítanunk kell."
    },
    {
      "id": "L18",
      "gond": "A 'bekötés' kifejezés itt is technikai, a funkciók nincsenek 'zárva' a természetes magyar beszédben.",
      "uj_szoveg": "Amíg a beállítások tartanak, néhány funkció még nem érhető el. Utána minden megnyílik."
    },
    {
      "id": "L20",
      "gond": "A 24–48 óra kimondva lassú és kissé bürokratikus hatású, természetesebb napokban kifejezni.",
      "uj_szoveg": "Ha elakadsz, kérj visszahívást: csapatunk egy-két munkanapon belül keresni fog."
    }
  ]
}
